<template><div class="mx-auto max-w-5xl px-4 py-8"><div class="mb-6"><NuxtLink to="/account" class="text-sm font-bold text-blue-600">← My Account</NuxtLink><h1 class="mt-2 text-3xl font-black text-slate-900">My Reviews</h1><p class="text-slate-500">Reviews you have submitted for verified purchases.</p></div><div v-if="loading" class="kc-panel p-6">Loading…</div><div v-else-if="!rows.length" class="kc-panel p-8 text-center text-slate-500">You haven't submitted any product reviews yet.</div><div v-else class="space-y-4"><article v-for="r in rows" :key="r.id" class="kc-panel p-5"><div class="flex items-start justify-between gap-4"><div><NuxtLink :to="`/product/${r.products?.slug}#reviews`" class="font-black text-blue-700">{{ r.products?.name }}</NuxtLink><div class="mt-1 text-amber-400">{{ '★'.repeat(r.rating)+'☆'.repeat(5-r.rating) }}</div></div><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold uppercase text-slate-600">{{ r.status }}</span></div><h2 class="mt-3 font-bold">{{ r.title }}</h2><p class="mt-1 whitespace-pre-line text-sm text-slate-700">{{ r.review }}</p><NuxtLink :to="`/product/${r.products?.slug}#reviews`" class="mt-3 inline-block text-sm font-bold text-blue-600">View / edit review →</NuxtLink></article></div></div></template>
<script setup lang="ts">const supabase=useSupabaseClient();const rows=ref<any[]>([]),loading=ref(true);onMounted(async()=>{try{const {data:{session}}=await supabase.auth.getSession();if(!session?.access_token){await navigateTo('/auth/signin?redirect=/account/reviews');return}rows.value=await $fetch('/api/reviews/mine',{headers:{Authorization:`Bearer ${session.access_token}`}})}finally{loading.value=false}});</script>
